package net.civeira.phylax.feature.template.themeversion.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.feature.template.themeversion.application.visibility.ThemeVersionVisibilityCheck;

public class TenantAccessible {

  /**
   * @autogenerated VisibilityPolicyGenerator
   * @param filter
   */
  public void filterVisibles(@Observes ThemeVersionVisibilityCheck filter) {
    Actor actor = filter.getActor();
    if (!(actor.hasScope("platform:global_access"))) {
      filter.peek(fl -> fl.setThemeTenantAccessible(actor.getTenant()));
    }
  }
}
